<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Student ID Cards</h1><p>Filter persisted students and print approved cards.</p></div><button class="btn btn--primary" type="button" onclick="window.print()">Print</button></header><form class="filter-bar filter-bar--compact" method="get"><div class="module-field"><label>Search Student</label><input class="module-input" name="search" value="<?= e($search) ?>"></div><div class="module-field"><label>Class</label><select class="module-select" name="class"><option value="">All Classes</option><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>" <?= $selectedClass==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></div><button class="btn btn--secondary">Filter</button></form><div class="style-options"><button class="style-option is-active" type="button">Default</button><button class="style-option" type="button">Style 1</button><button class="style-option" type="button">Style 2</button><button class="style-option" type="button">Style 3</button><button class="style-option" type="button">Style 4</button></div><div class="metric-grid"><?php foreach($students as$s):?><article class="module-card"><div class="module-card__body" style="text-align:center"><?php if($s['picture_path']):?><img src="<?= asset('../'.$s['picture_path']) ?>" alt="" style="width:80px;height:80px;object-fit:cover;border-radius:50%"><?php endif ?><h3><?= e($s['student_name']) ?></h3><p><?= e($institute['name']) ?></p><p><strong><?= e($s['registration_no']) ?></strong><br><?= e($s['class_name']) ?></p></div></article><?php endforeach ?><?php if(!$students):?><div class="compact-empty"><h3>No Students Found</h3></div><?php endif ?></div></div></div></main>
